// THROWAWAY UI prototype. Isolated from Next routes/SEO/paid data. State is in memory.
// Question: map-first (A), journal-first (B), or shareable passport (C)?
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const [airports,land]=await Promise.all([fetch('/assets/airports.json').then(r=>r.json()),fetch('/assets/land.json').then(r=>r.json())]);
const airport=Object.fromEntries(airports.map(a=>[a.code,a]));
const demo=[['SVX','IST','2025-09-14','TK 476'],['IST','CDG','2025-09-18','TK 1823'],['CDG','IST','2026-02-21','TK 1828'],['IST','SVX','2026-02-22','TK 475'],['SVX','DXB','2026-09-03','FZ 980'],['DXB','BKK','2026-09-04','EK 372']].map((f,id)=>({id,from:f[0],to:f[1],date:f[2],number:f[3]}));
let flights=structuredClone(demo),isDemo=true,period='',selected=null,editing=null,nextId=20,choice={from:null,to:null},box=null,shareSvg='';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Math.round(n).toLocaleString('ru-RU');
const xy=a=>[(a.lon+180)*1000/360,(90-a.lat)*1000/360];
const geometry=land.map(r=>'M'+r.map(([lon,lat])=>xy({lon,lat}).map(x=>x.toFixed(2)).join(',')).join('L')+'Z').join('');
function km(f){let a=airport[f.from],b=airport[f.to],rad=Math.PI/180;let dlat=(b.lat-a.lat)*rad,dlon=(b.lon-a.lon)*rad;return 6371*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2)));}
function visible(){return flights.filter(f=>!period||f.date?.startsWith(period));}
function totals(){let f=visible(),codes=[...new Set(f.flatMap(x=>[x.from,x.to]))];return {flights:f.length,countries:new Set(codes.map(c=>airport[c].country)).size,km:f.reduce((n,f)=>n+km(f),0),codes};}
function fit(){let pts=totals().codes.map(c=>xy(airport[c]));if(!pts.length){box={x:360,y:50,w:470,h:310};return;}
 let xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),w=Math.max(135,Math.max(...xs)-Math.min(...xs)+95),h=Math.max(110,Math.max(...ys)-Math.min(...ys)+80),ratio=$('#mapWrap').clientWidth/$('#mapWrap').clientHeight;
 if(w/h<ratio)w=h*ratio;else h=w/ratio;
 box={x:(Math.min(...xs)+Math.max(...xs))/2-w/2,y:(Math.min(...ys)+Math.max(...ys))/2-h/2,w,h};}
function map(){let {codes}=totals();$('#map').setAttribute('viewBox',`${box.x} ${box.y} ${box.w} ${box.h}`);let grid='';for(let lon=-180;lon<=180;lon+=30){let x=xy({lon,lat:0})[0];grid+=`M${x} 0V500`;}for(let lat=-60;lat<=90;lat+=30){let y=xy({lon:0,lat})[1];grid+=`M0 ${y}H1000`;}
 const points=visible().map(f=>{let [x,y]=xy(airport[f.from]),[xx,yy]=xy(airport[f.to]);let dx=xx-x,dy=yy-y;let lift=Math.min(65,Math.hypot(dx,dy)*.3);return `<path class="flight-path${selected===f.id?' selected':''}" d="M${x} ${y} Q${(x+xx)/2} ${(y+yy)/2-lift} ${xx} ${yy}"/>`;}).join('');
 const scale=box.w/Math.max(300,$('#mapWrap').clientWidth);const labelPositions=[];let dots=codes.map(c=>{let [x,y]=xy(airport[c]),lx=x+7*scale,ly=y-6*scale;
 while(labelPositions.some(([ox,oy])=>Math.abs(ox-lx)<34*scale&&Math.abs(oy-ly)<12*scale))ly+=14*scale;
 labelPositions.push([lx,ly]);return `<circle class="airport-dot" cx="${x}" cy="${y}" r="${2.6*scale}"/><text class="airport-label" x="${lx}" y="${ly}" style="font-size:${10*scale}px">${c}</text>`;}).join('');
 $('#map').innerHTML=`<path class="graticule" d="${grid}"/><path class="land" d="${geometry}"/>${points}${dots}`;
 $('.map-empty').hidden=visible().length>0;
}
function render(reset=true){let t=totals();if(reset||!box)fit();map();$('#stats').innerHTML=`<div class="stat"><b>${t.flights}</b><span>перелётов</span></div><div class="stat"><b>${t.countries}</b><span>стран на карте</span></div><div class="stat"><b>${fmt(t.km)}</b><span>км по прямой ≈</span></div>`;
 $('#journalCount').textContent=period?`История за ${period} год`:'Все маршруты в одном месте';
 $('.demo-bar').querySelector('span').innerHTML=`<i></i>${isDemo?' Пример вашей карты':' Ваша карта · только в этой сессии'}`;$('#clearDemo').textContent=isDemo?'Начать свою':'Показать пример';
 $('#flightList').innerHTML=visible().slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(f=>`<article class="flight${selected===f.id?' selected':''}" tabindex="0" role="button" aria-label="${esc(airport[f.from].city+' — '+airport[f.to].city)}" data-id="${f.id}"><div class="flight-top"><span>${f.date?new Date(f.date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short',year:'numeric'}):'Дата не указана'}${f.number?' · '+esc(f.number):''}</span><button aria-label="Изменить перелёт ${esc(f.from+' — '+f.to)}" data-edit="${f.id}">···</button></div><div class="route"><div><strong>${f.from}</strong><small>${esc(airport[f.from].city)}</small></div><div class="route-line"><span>✈</span></div><div><strong>${f.to}</strong><small>${esc(airport[f.to].city)}</small></div></div></article>`).join('')||'<div class="empty-list">Пока здесь чистый лист.<br>Добавьте первый перелёт — карта оживёт.</div>';
 $('#flightList').querySelectorAll('[data-id]').forEach(el=>{const choose=()=>{selected=+el.dataset.id;render(false);};el.onclick=e=>{if(!e.target.closest('[data-edit]'))choose();};el.onkeydown=e=>{if(e.key==='Enter'&&!e.target.closest('[data-edit]'))choose();};});
 $$('[data-edit]').forEach(el=>el.onclick=()=>openForm(+el.dataset.edit));
}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function close(d){d.close();document.body.style.overflow='';}
function open(d){d.showModal();document.body.style.overflow='hidden';}
$$('dialog .close').forEach(b=>b.onclick=()=>close(b.closest('dialog')));$$('dialog').forEach(d=>{d.addEventListener('close',()=>document.body.style.overflow='');d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close(d);}});});
function openForm(id=null){editing=id;$('#flightForm').reset();$('#formError').textContent='';$$('.suggestions').forEach(e=>e.innerHTML='');let f=flights.find(f=>f.id===id);choice={from:f?.from||null,to:f?.to||null};for(const side of ['from','to']){let a=airport[choice[side]];$('#'+side).value=a?`${a.city} · ${a.code}`:'';$('#'+side).setAttribute('aria-expanded','false');}
 $('#date').value=f?.date||'';$('#number').value=f?.number||'';$('#formTitle').textContent=f?'Ваш перелёт':'Добавить перелёт';$('#flightForm .save').textContent=f?'Сохранить изменения':'Добавить на карту ↗';$('#deleteFlight')?.remove();if(f){let b=document.createElement('button');b.id='deleteFlight';b.type='button';b.textContent='Удалить перелёт';b.style='background:none;color:#ff837a;width:100%;padding:15px;margin-top:5px';b.onclick=()=>{let saved=f;flights=flights.filter(x=>x.id!==f.id);close($('#addDialog'));render();toast('Перелёт удалён · можно отменить');$('#toast').style.pointerEvents='auto';$('#toast').onclick=()=>{flights.push(saved);render();toast('Перелёт восстановлен');$('#toast').onclick=null;$('#toast').style.pointerEvents='none';};};$('#flightForm').append(b);}open($('#addDialog'));if(!f)$('#from').focus();}
for(const side of ['from','to']){let input=$('#'+side),list=$('#'+side+'Results');const show=()=>{let q=input.value.toLocaleLowerCase().trim();let rows=airports.filter(a=>`${a.city} ${a.code} ${a.name}`.toLocaleLowerCase().includes(q)).slice(0,6);list.innerHTML=rows.map(a=>`<button type="button" role="option" aria-selected="false" data-code="${a.code}"><span>${esc(a.city)}<small>${esc(a.name)}</small></span><b>${a.code}</b></button>`).join('')||'<p style="padding:12px">В демоверсии этого аэропорта пока нет.</p>';input.setAttribute('aria-expanded','true');list.querySelectorAll('button').forEach(b=>b.onclick=()=>{choice[side]=b.dataset.code;let a=airport[choice[side]];input.value=`${a.city} · ${a.code}`;list.innerHTML='';input.setAttribute('aria-expanded','false');if(side==='from')$('#to').focus();});};input.oninput=()=>{choice[side]=null;show();};input.onfocus=()=>{if(!choice[side])show();};input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();list.querySelector('button')?.focus();}if(e.key==='Escape'){list.innerHTML='';input.setAttribute('aria-expanded','false');}};}
$('.swap').onclick=()=>{[choice.from,choice.to]=[choice.to,choice.from];let a=$('#from').value;$('#from').value=$('#to').value;$('#to').value=a;$$('.suggestions').forEach(e=>e.innerHTML='');};
$('#flightForm').onsubmit=e=>{e.preventDefault();if(!choice.from||!choice.to){$('#formError').textContent='Выберите оба аэропорта из подсказок.';return;}if(choice.from===choice.to){$('#formError').textContent='Аэропорты вылета и прилёта должны отличаться.';return;}let f={id:editing??nextId++,from:choice.from,to:choice.to,date:$('#date').value,number:$('#number').value.trim()};if(editing===null)flights.push(f);else flights=flights.map(x=>x.id===editing?f:x);period='';$('#period').innerHTML='За всё время <span>⌄</span>';selected=f.id;close($('#addDialog'));render();toast(editing===null?'Перелёт добавлен на вашу карту':'Изменения сохранены');};
$('#clearDemo').onclick=()=>{if(isDemo){flights=[];isDemo=false;}else{flights=structuredClone(demo);isDemo=true;}selected=null;period='';$('#period').innerHTML='За всё время <span>⌄</span>';render();};
$('#period').onclick=()=>{let ps=['','2026','2025'];period=ps[(ps.indexOf(period)+1)%3];$('#period').innerHTML=(period||'За всё время')+' <span>⌄</span>';render();};
$('#fit').onclick=()=>{fit();map();};for(const [id,f] of [['zoomIn',.8],['zoomOut',1.25]])$('#'+id).onclick=()=>{if(box.w*f<50||box.w*f>1100)return;box={x:box.x+box.w*(1-f)/2,y:box.y+box.h*(1-f)/2,w:box.w*f,h:box.h*f};map();};
function theme(){let root=document.documentElement;root.dataset.theme=root.dataset.theme==='dark'?'light':'dark';$('#theme').textContent=root.dataset.theme==='dark'?'☼':'☾';}
$('#theme').onclick=theme;$('#settings').onclick=theme;
const variants=['A','B','C'],labels={A:'A · Карта',B:'B · Журнал',C:'C · Паспорт'};let variant=new URLSearchParams(location.search).get('variant')||'A';if(!variants.includes(variant))variant='A';
function changeVariant(v){variant=v;document.body.dataset.variant=v;$('#variantLabel').textContent=labels[v];$('.passport-footer').hidden=v!=='C';history.replaceState(null,'','?variant='+v);if(box)render();}
function cycle(n){changeVariant(variants[(variants.indexOf(variant)+n+3)%3]);}$('#prevVariant').onclick=()=>cycle(-1);$('#nextVariant').onclick=()=>cycle(1);document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,[contenteditable]')||$('dialog[open]'))return;if(e.key==='ArrowLeft')cycle(-1);if(e.key==='ArrowRight')cycle(1);});
function makeShare(){let t=totals();let cloned=$('#map').cloneNode(true);cloned.setAttribute('x','30');cloned.setAttribute('y','220');cloned.setAttribute('width','840');cloned.setAttribute('height','440');cloned.removeAttribute('id');cloned.querySelectorAll('.land').forEach(e=>{e.setAttribute('fill','#202b3a');e.setAttribute('stroke','#354359');e.setAttribute('stroke-width','.5');});cloned.querySelectorAll('.graticule').forEach(e=>e.remove());cloned.querySelectorAll('.flight-path').forEach(e=>{e.setAttribute('fill','none');e.setAttribute('stroke','#2a9aff');e.setAttribute('stroke-width','2');});cloned.querySelectorAll('.airport-dot').forEach(e=>{e.setAttribute('fill','#fff');e.setAttribute('stroke','#0a84ff');});cloned.querySelectorAll('text').forEach(e=>{e.setAttribute('fill','#fff');e.setAttribute('stroke','#101319');e.setAttribute('stroke-width','1');e.setAttribute('paint-order','stroke');e.setAttribute('font-family','Arial,sans-serif');e.setAttribute('font-weight','600');});
 shareSvg=`<svg xmlns="http://www.w3.org/2000/svg" width="900" height="1000" viewBox="0 0 900 1000"><rect width="900" height="1000" rx="30" fill="#101319"/><text x="60" y="85" fill="#9096a2" font-family="Arial" font-size="18" letter-spacing="4">МОЯ ИСТОРИЯ ПУТЕШЕСТВИЙ</text><text x="60" y="155" fill="white" font-family="Arial" font-size="55" font-weight="bold">Мир становится ближе.</text>${cloned.outerHTML}<path d="M60 700H840" stroke="#ffffff20"/><g fill="white" font-family="Arial" text-anchor="middle" font-size="50"><text x="175" y="785">${t.flights}</text><text x="450" y="785">${t.countries}</text><text x="725" y="785">${fmt(t.km)}</text></g><g fill="#9096a2" font-family="Arial" text-anchor="middle" font-size="18"><text x="175" y="825">перелётов</text><text x="450" y="825">стран на карте</text><text x="725" y="825">км по прямой ≈</text></g><text x="60" y="940" fill="white" font-family="Arial" font-size="25" font-weight="bold">✈ airportsboard</text><text x="840" y="940" fill="#9096a2" font-family="Arial" font-size="15" text-anchor="end">${isDemo?'ДЕМОНСТРАЦИОННЫЕ ДАННЫЕ':'МОЯ КАРТА ПЕРЕЛЁТОВ'}</text></svg>`;
 $('#sharePreview').innerHTML=shareSvg;open($('#shareDialog'));}
$('#download').onclick=async()=>{let url=URL.createObjectURL(new Blob([shareSvg],{type:'image/svg+xml'}));let img=new Image();img.onload=()=>{let canvas=document.createElement('canvas');canvas.width=900;canvas.height=1000;canvas.getContext('2d').drawImage(img,0,0);canvas.toBlob(blob=>{let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download='my-flights-airportsboard.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);},'image/png');URL.revokeObjectURL(url);toast('Картинка готова к сохранению');};img.onerror=()=>toast('Не удалось собрать картинку. Попробуйте ещё раз.');img.src=url;};
$$('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'add':openForm();break;case'share':makeShare();break;case'top':window.scrollTo({top:0,behavior:'smooth'});break;default:toast('В прототипе работает раздел «Перелёты»');}});
changeVariant(variant);render();let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>render(),100);});
